import {makeAssignmentReportFixture} from './assignment-report-fixture.mjs';
export function makeTeacherPortalFixture(){
 const report=makeAssignmentReportFixture();
 const classes=[{id:'c1',name:'Toán 9A1',grade:9,academicYear:'2026–2027',isActive:true,studentCount:35},{id:'c2',name:'Toán 9A2',grade:9,academicYear:'2026–2027',isActive:true,studentCount:18},{id:'c3',name:'Toán 8A1',grade:8,academicYear:'2026–2027',isActive:true,studentCount:0}];
 const assignments=Array.from({length:36},(_,i)=>({...report.assignment,id:`a${i+1}`,classId:i<24?'c1':'c2',title:`${['Ôn tập căn thức','Phương trình bậc hai','Hình học đường tròn','Kiểm tra giữa kỳ'][i%4]} · Bài ${i+1}`,status:i%5===0?'DRAFT':i%5===1?'CLOSED':'PUBLISHED',dueDate:i%5===1?'2026-10-01T10:00:00Z':i%3===0?'2026-12-01T10:00:00Z':null,totalStudents:i<24?35:18,totalSubmissions:i%5===0?0:15,averageScore:i%5===0?null:5.8,settings:{...report.assignment.settings,folder:['Đại số','Hình học','Ôn thi'][i%3]}}));
 const bank=Array.from({length:66},(_,i)=>{const type=i%22<12?'SINGLE_CHOICE':i%22<16?'TRUE_FALSE':'SHORT_ANSWER';const q={...report.questions[i%22],id:`bank${i+1}`,skillId:`skill${i%3+1}`,authorId:'teacher-portal-fixture',status:'PUBLISHED',difficulty:['EASY','MEDIUM','HARD','VERY_HARD'][i%4],cognitiveLevel:'REMEMBERING',questionType:type,content:type==='TRUE_FALSE'?'Xét tính đúng sai của các khẳng định về căn bậc hai.':type==='SHORT_ANSWER'?'Tính $2 + 2$.':report.questions[i%22].content};if(type==='TRUE_FALSE'){q.statements=['a','b','c','d'].map((key,j)=>({key,content:`$${j+1}^2 = ${(j+1)**2}$`,isCorrect:true}));q.options=[];}if(type==='SHORT_ANSWER'){q.shortAnswer={mode:'NUMERIC',acceptedAnswers:['4'],tolerance:1e-9,instructions:'Nhập số, không kèm đơn vị.',caseSensitive:false};q.options=[];}return q;});
 const details=id=>{const classroom=classes.find(c=>c.id===id);return {...classroom,students:report.roster.slice(0,classroom.studentCount).map(r=>({...r,email:`${r.username}@example.test`,joinedAt:'2026-09-01T00:00:00Z'})),inviteCodes:[{id:'code1',codePrefix:'MATH',usedCount:35,maxUses:50,expiresAt:'2026-12-01T00:00:00Z',isRevoked:false}]};};
 const assignmentReport=id=>{const a=assignments.find(a=>a.id===id)||assignments[0];return {...report,assignment:{...a},roster:report.roster.slice(0,a.totalStudents)};};
 return {classes,assignments,bank,details,assignmentReport};
}
